def to_roman(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("Input must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("Input must be between 1 and 3999")

    val = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    sym = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    result = []
    for v, s in zip(val, sym):
        while n >= v:
            result.append(s)
            n -= v
    return "".join(result)


def from_roman(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if not s:
        raise ValueError("Input must not be empty")
    if not s.isupper():
        raise ValueError("Input must be upper-case")
    if not all(c in "MDCLXVI" for c in s):
        raise ValueError("Input contains invalid characters")

    # Check canonical form by converting to roman and back
    # First, parse the roman numeral
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    total = 0
    prev = 0
    for c in reversed(s):
        curr = roman_map[c]
        if curr < prev:
            total -= curr
        else:
            total += curr
        prev = curr

    # Verify it's in canonical form by checking that to_roman(total) == s
    try:
        if to_roman(total) != s:
            raise ValueError("Input is not in canonical form")
    except ValueError:
        raise ValueError("Input is not in canonical form")

    return total
